  function titleJaccard(a, b) {
    var ka = Object.keys(a), kb = Object.keys(b), inter = 0;
    if (!ka.length || !kb.length) return 0;
    ka.forEach(function (k) { if (b[k]) inter++; });
    return inter / (ka.length + kb.length - inter);
  }
